insert into assessments (slug, title, short_description, long_description, icon, category_id, engine_type, difficulty, estimated_duration_minutes, question_count, featured, access, status) values ('social-cognition-assessment', 'Social Cognition Assessment', 'Reading intentions, perspective-taking, and interpreting social scenarios — the cognitive side of understanding people.', convert_from(decode('', 'base64'), 'UTF8'), 'users', (select id from assessment_categories where key = 'emotional'), ('standard_questionnaire')::assessment_engine_type, ('medium')::assessment_difficulty, 15, 20, false, ('free')::assessment_access, ('published')::assessment_status)
