insert into result_ranges (assessment_id, dimension_key, min_score, max_score, title, description, recommendations, icon, "order") values ((select id from assessments where slug = 'social-cognition-assessment'), 'overall', 0, 30, 'Developing', 'Social scenarios are often read at face value — the literal words rather than what the speaker actually believed, wanted, or intended.', ARRAY['When someone says something surprising, pause and ask what they might believe that would make it make sense', convert_from(decode('UHJhY3RpY2Ugbm90aWNpbmcgdGhlIGRpZmZlcmVuY2UgYmV0d2VlbiB3aGF0J3Mgc2FpZCBhbmQgd2hhdCdzIG1lYW50IGluIGNvbnZlcnNhdGlvbnMgeW91IG9ic2VydmU=', 'base64'), 'UTF8'), 'Watch for social cues like tone and context that signal irony, jokes, or tact']::text[], NULL, 1);
insert into result_ranges (assessment_id, dimension_key, min_score, max_score, title, description, recommendations, icon, "order") values ((select id from assessments where slug = 'social-cognition-assessment'), 'overall', 31, 50, 'Average', 'Straightforward social cues like obvious jokes or lies are read correctly, but subtler cases — white lies, persuasion, double meanings — are harder to untangle.', ARRAY['Practice distinguishing white lies (said to protect feelings) from ordinary lies (said for self-interest)', convert_from(decode('UGF5IGF0dGVudGlvbiB0byBhIHNwZWFrZXIncyBsaWtlbHkgZ29hbCwgbm90IGp1c3QgdGhlaXIgbGl0ZXJhbCB3b3Jkcywgd2hlbiBpbnRlcnByZXRpbmcgcGVyc3Vhc2lvbg==', 'base64'), 'UTF8')]::text[], NULL, 2);
insert into result_ranges (assessment_id, dimension_key, min_score, max_score, title, description, recommendations, icon, "order") values ((select id from assessments where slug = 'social-cognition-assessment'), 'overall', 51, 70, 'Strong', 'Reliably infers what other people believe and intend, correctly separating that from objective reality in most scenarios.', ARRAY[convert_from(decode('UHJhY3RpY2Ugd2l0aCBsYXllcmVkIHNjZW5hcmlvcyB3aGVyZSBhIGNoYXJhY3RlcidzIGJlbGllZiBpcyBpdHNlbGYgbWlzdGFrZW4=', 'base64'), 'UTF8'), 'Apply this skill deliberately in real conversations — check your read against what actually happened']::text[], NULL, 3);
insert into result_ranges (assessment_id, dimension_key, min_score, max_score, title, description, recommendations, icon, "order") values ((select id from assessments where slug = 'social-cognition-assessment'), 'overall', 71, 85, 'Very Strong', 'Consistently accurate at reading intentions, irony, and non-literal language, rarely taking a figurative statement at face value.', ARRAY['This is a strong foundation for roles involving negotiation, mediation, or coaching', 'Notice how this skill helps you catch misunderstandings before they escalate']::text[], NULL, 4);
insert into result_ranges (assessment_id, dimension_key, min_score, max_score, title, description, recommendations, icon, "order") values ((select id from assessments where slug = 'social-cognition-assessment'), 'overall', 86, 100, 'Exceptional', 'Expert-level social cognition — mental states, intentions, and non-literal meaning are read quickly and accurately across every scenario type.', ARRAY['Consider where this strength is most valuable — teaching, therapy, leadership, and mediation all lean on it heavily', convert_from(decode('TWVudG9yIG90aGVycyBvbiBkaXN0aW5ndWlzaGluZyB3aGF0J3Mgc2FpZCBmcm9tIHdoYXQncyBtZWFudA==', 'base64'), 'UTF8')]::text[], NULL, 5);
